export type Permission = (typeof PERMISSIONS)[number];

/** Every role, from anonymous guest to super admin. */
export const ROLES = [
  "guest",
  "customer",
  "loyalty_member",
  "customer_service",
  "merchandiser",
  "pricing_manager",
  "inventory_manager",
  "fulfillment",
  "vendor",
  "manager",
  "admin",
  "super_admin",
] as const;

export type Role = (typeof ROLES)[number];

/** Roles that work in the back office. Merchants (`vendor`) are not staff (D-060). */
export const STAFF_ROLES = [
  "customer_service",
  "merchandiser",
  "pricing_manager",
  "inventory_manager",
  "fulfillment",
  "manager",
  "admin",
  "super_admin",
] as const satisfies readonly Role[];

