/**
 * Operations manager: runs the business day to day. Everything the specialist
 * roles can do (customer service with unlimited refunds, catalogue, pricing,
 * stock, fulfilment), approves and suspends merchant shops and products, and
 * reads reports, settings, staff and the audit log. Doesn't change store
 * settings or staff accounts: that stays with admins and platform owners.
 */
const MANAGER: readonly Permission[] = [
  ...new Set([
    ...CUSTOMER_SERVICE,
    ...MERCHANDISER,
    ...PRICING_MANAGER,
    ...INVENTORY_MANAGER,
    ...FULFILLMENT,
    "orders.refund_unlimited",
    "merchants.manage",
    "reports.read",
    "settings.read",
    "users.read",
    "audit.read",
  ] as const),
];

/** Admin: a manager who also runs store settings and staff (invites, roles, sessions). */
const ADMIN: readonly Permission[] = [
  ...new Set([
    ...MANAGER,
    "settings.write",
    "users.invite",
    "users.assign_role",
    "users.revoke_sessions",
    "emails.outbox.read",
  ] as const),
];

/** Platform owner (internal role name: super_admin): everything, including admins and integrations. */
const SUPER_ADMIN: readonly Permission[] = [
  ...new Set([...ADMIN, "audit.export", "integrations.write"] as const),
];

/** The permissions each role grants. */
export const ROLE_PERMISSIONS: Readonly<Record<Role, readonly Permission[]>> = {
  guest: GUEST,
  customer: CUSTOMER,
  loyalty_member: LOYALTY_MEMBER,
  customer_service: CUSTOMER_SERVICE,
  merchandiser: MERCHANDISER,
  pricing_manager: PRICING_MANAGER,
  inventory_manager: INVENTORY_MANAGER,
  fulfillment: FULFILLMENT,
  vendor: VENDOR,
  manager: MANAGER,
  admin: ADMIN,
  super_admin: SUPER_ADMIN,
};

/** Human-readable role names for the back office. */
export const ROLE_LABELS: Readonly<Record<Role, string>> = {
  guest: "Guest",
  customer: "Customer",
  loyalty_member: "Rewards member",
  customer_service: "Customer service",
  merchandiser: "Merchandiser",
  pricing_manager: "Pricing manager",
  inventory_manager: "Inventory manager",
  fulfillment: "Fulfilment",
  vendor: "Merchant",
  manager: "Operations manager",
  admin: "Admin",
  super_admin: "Platform owner",
};

/** Type guard for role strings, e.g. from token claims. */
export function isRole(value: unknown): value is Role {
  return typeof value === "string" && (ROLES as readonly string[]).includes(value);
}

/** Type guard for permission strings. */
export function isPermission(value: unknown): value is Permission {
  return typeof value === "string" && (PERMISSIONS as readonly string[]).includes(value);
}

/** All permissions a role grants. */
export function permissionsFor(role: Role): readonly Permission[] {
  return ROLE_PERMISSIONS[role];
}

/** Whether a role grants a permission. */
export function hasPermission(role: Role, permission: Permission): boolean {
  return ROLE_PERMISSIONS[role].includes(permission);
}

/** Whether a role grants at least one of the permissions. */
export function hasAnyPermission(role: Role, permissions: readonly Permission[]): boolean {
  return permissions.some((permission) => hasPermission(role, permission));
}

/** Roles holding a permission, e.g. for tests and admin UI explanations. */
export function rolesWith(permission: Permission): Role[] {
  return ROLES.filter((role) => hasPermission(role, permission));
}

/** Whether a role works in the back office. */
export function isStaffRole(role: Role): boolean {
  return (STAFF_ROLES as readonly Role[]).includes(role);
}

/** Roles only a platform owner may grant or change: admin and platform owner. */
export const OWNER_ONLY_ROLES = ["admin", "super_admin"] as const satisfies readonly Role[];

export function isOwnerOnlyRole(role: Role): boolean {
  return (OWNER_ONLY_ROLES as readonly Role[]).includes(role);
}

export interface RoleChange {
  actorUid: string;
  actorRole: Role;
  targetUid: string;
  targetCurrentRole: Role;
  nextRole: Role;
}

export type RoleChangeDecision =
  | { allowed: true }
  | {
      allowed: false;
      reason:
        "no_permission" | "self_change" | "protected_target" | "protected_role" | "invalid_role";
    };

/**
 * Role assignment policy:
 * - only roles with `users.assign_role` (admin, super_admin) may assign;
 * - nobody changes their own role (no self-elevation, no self-lockout);
 * - only a platform owner (super_admin) may grant admin or platform owner, or
 *   change someone who holds either: admins manage the staff below them;
 * - `guest` is a session state, never an assignable role.
 */
export function canAssignRole(change: RoleChange): RoleChangeDecision {
  const { actorUid, actorRole, targetUid, targetCurrentRole, nextRole } = change;

  if (!hasPermission(actorRole, "users.assign_role"))
    return { allowed: false, reason: "no_permission" };
  if (actorUid === targetUid) return { allowed: false, reason: "self_change" };
  if (nextRole === "guest") return { allowed: false, reason: "invalid_role" };
  if (actorRole !== "super_admin") {
    if (isOwnerOnlyRole(targetCurrentRole)) return { allowed: false, reason: "protected_target" };
    if (isOwnerOnlyRole(nextRole)) return { allowed: false, reason: "protected_role" };
  }
  return { allowed: true };
}

/**
 * Merchant pages anyone may open: signing up, signing in and account recovery.
 * Everything else under `/merchant` needs the merchant role.
 */
export const MERCHANT_PUBLIC_PATHS = [
  "/merchant/register",
  "/merchant/sign-in",
  "/merchant/forgot-password",
  "/merchant/reset-password",
  "/merchant/verify-email",
] as const;

/**
 * Pages under protected prefixes that anyone may open: merchant sign-up and
 * recovery, the staff sign-in page, and the wishlist (guests see this device's list, members their
 * synced one).
 */
const PUBLIC_PATHS: readonly string[] = [
  ...MERCHANT_PUBLIC_PATHS,
  "/account/wishlist",
  // The team's own sign-in page.
  "/admin/sign-in",
];

/**
 * The only role changes server code may make without a signed-in admin: a
 * shopper becoming a merchant when they register a shop (D-061), and a
 * customer joining rewards from their own account (D-091).
 */
export function canSystemGrant(currentRole: Role, nextRole: Role): boolean {
  // A shopper joining rewards, from their own account.
  if (nextRole === "loyalty_member") return currentRole === "customer";
  return nextRole === "vendor" && (currentRole === "customer" || currentRole === "loyalty_member");
}

/** Route prefixes and the permission each requires. Longest prefix wins. */
export const ROUTE_PERMISSIONS: ReadonlyArray<{ prefix: string; permission: Permission }> = [
  { prefix: "/account", permission: "account.manage" },
  { prefix: "/admin", permission: "admin.access" },
  { prefix: "/admin/orders", permission: "orders.read" },
  { prefix: "/admin/returns", permission: "returns.read" },
  { prefix: "/admin/customers", permission: "customers.read" },
  { prefix: "/admin/catalog", permission: "catalog.read_drafts" },
  { prefix: "/admin/categories", permission: "merch.write" },
  { prefix: "/admin/content", permission: "content.write" },
  { prefix: "/admin/reviews", permission: "reviews.moderate" },
  { prefix: "/admin/pricing", permission: "pricing.write" },
  { prefix: "/admin/promotions", permission: "promotions.write" },
  { prefix: "/admin/inventory", permission: "inventory.read" },
  { prefix: "/admin/fulfillment", permission: "fulfillment.write" },
  { prefix: "/admin/merchants", permission: "merchants.review" },
  { prefix: "/admin/reports", permission: "reports.read" },
  { prefix: "/admin/users", permission: "users.read" },
  { prefix: "/admin/settings", permission: "settings.read" },
  { prefix: "/admin/audit", permission: "audit.read" },
  { prefix: "/admin/emails", permission: "emails.outbox.read" },
  { prefix: "/merchant", permission: "vendor.catalog.write" },
  // Shop pages are private: merchant and shop names are never shown to shoppers.
  { prefix: "/shops", permission: "shops.preview" },
];

function matchesPrefix(pathname: string, prefix: string): boolean {
  return pathname === prefix || pathname.startsWith(`${prefix}/`);
}

/** The permission a path requires, or null for public routes. */
export function requiredPermissionForPath(pathname: string): Permission | null {
  if (PUBLIC_PATHS.some((prefix) => matchesPrefix(pathname, prefix))) return null;
  let best: { prefix: string; permission: Permission } | null = null;
  for (const rule of ROUTE_PERMISSIONS) {
    if (
      matchesPrefix(pathname, rule.prefix) &&
      (!best || rule.prefix.length > best.prefix.length)
    ) {
      best = rule;
    }
  }
  return best?.permission ?? null;
}
